<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'; import { isEmail, isWhatsapp, maskWhatsapp } from '../../utils/validation'
const router = useRouter(); const store = useCompanyOnboardingStore(); const samePhone = ref(false); const error = ref('')
function togglePhone() { samePhone.value = !samePhone.value; if (samePhone.value) store.updateCompany({ phone: store.state.owner.whatsapp }) }
function next() { const company = store.state.company; error.value = !isEmail(company.email) ? 'Informe um e-mail válido.' : !isWhatsapp(company.phone) ? 'Informe um telefone válido.' : ''; if (error.value) return; store.nextStep(); router.push('/cadastro/endereco') }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Como podemos entrar em contato com a empresa?</h1><div class="mt-10 space-y-5"><label class="block"><span class="text-sm font-medium">E-mail</span><input v-model="store.state.company.email" type="email" autocomplete="email" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" /></label><label class="block"><span class="text-sm font-medium">Telefone / WhatsApp</span><input :value="store.state.company.phone" inputmode="tel" class="mt-2 h-14 w-full rounded-lg border border-neutral-300 px-4 outline-none focus:border-neutral-900 focus:ring-2 focus:ring-lime-200" @input="store.updateCompany({ phone: maskWhatsapp(($event.target as HTMLInputElement).value) })" /></label><label class="flex items-center gap-3 text-sm text-neutral-700"><input type="checkbox" :checked="samePhone" class="h-4 w-4 accent-lime-500" @change="togglePhone" />Usar o mesmo WhatsApp do responsável</label><p v-if="error" class="text-sm text-red-600">{{ error }}</p><BaseButton class="min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" @click="next">Continuar</BaseButton></div></section></template>
